-- FrioZvanHub OnlineKey
local __fzh_b64 = ''
local __fzh_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local __fzh_out = {}
local __fzh_buf, __fzh_bits = 0, 0
for i=1,#__fzh_b64 do
  local c=__fzh_b64:sub(i,i)
  if c ~= "=" then
    local p=__fzh_chars:find(c,1,true)
    if p then
      __fzh_buf=__fzh_buf*64+(p-1)
      __fzh_bits=__fzh_bits+6
      if __fzh_bits>=8 then
        __fzh_bits=__fzh_bits-8
        __fzh_out[#__fzh_out+1]=string.char(math.floor(__fzh_buf/(2^__fzh_bits))%256)
        __fzh_buf=__fzh_buf%(2^__fzh_bits)
      end
    end
  end
end
local __fzh_load=loadstring or load
assert(__fzh_load,"loadstring unavailable")
return __fzh_load(table.concat(__fzh_out))()
